# assistant (Claude, Anthropic) under the direction of the Datanauts Brasil team. The project idea,
# scope and decisions are the team's own. No data or results are generated by AI: every value comes
# from the public sources listed in REFERENCES.md and data/<field>/manifesto.json.
# Rotare | coleta completa com um comando.  Uso:  .\coletar.ps1
# Outro ponto:  .\coletar.ps1 -Lat -12.60 -Lon -55.95 -Nome sorriso
param(
  [double]$Lat = -12.60,
  [double]$Lon = -55.95,
  [string]$Nome = "sorriso",
  [string]$Inicio = "2014-01-01",
  [string]$Fim = "2025-12-31",
  [string]$Fontes = "power,power_historico,oni,solo,relevo,ecocrop,calendario_fao,zarc,sidra,chirps,imerg_gee,modis,smap,uso_terra,mapbiomas",
  [int]$InicioSafra = 0,
  [switch]$Refazer
)
Set-Location $PSScriptRoot
if (-not (Test-Path ".venv")) {
  python -m venv .venv
  .\.venv\Scripts\python -m pip install -q -r requirements.txt
}
$env:PYTHONIOENCODING = "utf-8"
$extra = @(); if ($Refazer) { $extra += "--refazer" }
.\.venv\Scripts\python coleta_rotare.py --lat $Lat --lon $Lon --nome $Nome --inicio $Inicio --fim $Fim --saida ..\data --fontes $Fontes --inicio-safra $InicioSafra @extra
# CSVs para o time e banco DuckDB com todos os talhoes
.\.venv\Scripts\python exportar_csv.py
.\.venv\Scripts\python montar_banco.py
